package com.campus.controller;import com.campus.common.Result;import com.campus.security.Tokens;import com.campus.mapper.UserMapper;import com.campus.service.AdvertisementService;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/advertisements")public class AdvertisementController{final AdvertisementService s;final Tokens t;final UserMapper u;AdvertisementController(AdvertisementService s,Tokens t,UserMapper u){this.s=s;this.t=t;this.u=u;}long me(String h){if(h==null||!h.startsWith("Bearer "))throw new IllegalArgumentException("请先登录");return t.verify(h.substring(7));}void admin(String h){if(!"ADMIN".equals(u.selectById(me(h)).getRole()))throw new IllegalArgumentException("无管理员权限");}@GetMapping public Result<?> active(@RequestParam(required=false)String placement){return Result.ok(s.active(placement));}@PostMapping("/{id}/impression")public Result<?> impression(@PathVariable long id){s.impression(id);return Result.ok(null);}@PostMapping("/{id}/click")public Result<?> click(@PathVariable long id){s.click(id);return Result.ok(null);}@PostMapping public Result<?> create(@RequestHeader("Authorization")String h,@RequestBody Map<String,Object>x){return Result.ok(Map.of("id",s.create(me(h),x)));}@GetMapping("/admin/stats")public Result<?> stats(@RequestHeader("Authorization")String h){admin(h);return Result.ok(s.stats());}@GetMapping("/admin")public Result<?> list(@RequestHeader("Authorization")String h,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size){admin(h);return Result.ok(s.list(page,size));}@PutMapping("/{id}/status")public Result<?> status(@RequestHeader("Authorization")String h,@PathVariable long id,@RequestBody Map<String,String>x){admin(h);s.status(id,x.get("status"));return Result.ok(null);}}
